const net = require('net');

// Define the host and port number
const HOST = 'localhost';
const PORT = 8000;

// Create a new Net listener
const server = net.createServer((socket) => {
    console.log(`Client connected: ${socket.remoteAddress}:${socket.remotePort}`);

    // When client disconnects, clean up resources
    socket.on('end', () => {
        console.log('Connection closed');
    });

    // On every received message, echo back the same message
    socket.on('data', function(data) {
        const response = `${new Date().toISOString()} - Received: ${data.toString()}`;
        console.log(response);
        socket.write(response);
    });
});

// Listen on provided port
server.listen(PORT, HOST, () => {
    console.log(`Server listening at http://${HOST}:${PORT}`);
});
```

